package br.com.social.post; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="posts") public class Post{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;private String authorEmail;private String authorName;@Column(nullable=false,length=2000)private String content;@Column(nullable=false)private LocalDateTime createdAt;@Column(nullable=false)private boolean hidden=false;public Post(){}public Post(String e,String n,String c){authorEmail=e;authorName=n;content=c;createdAt=LocalDateTime.now();}public Long getId(){return id;}public String getAuthorEmail(){return authorEmail;}public String getAuthorName(){return authorName;}public String getContent(){return content;}public LocalDateTime getCreatedAt(){return createdAt;}public boolean isHidden(){return hidden;}public void setHidden(boolean v){hidden=v;}}